before.content:
* { box-sizing: border-box; }
body { margin: 0; min-width: 320px; }
button, textarea { font: inherit; }
button { border: 1px solid #ccd2dc; border-radius: .7rem; background: #fff; padding: .55rem .9rem; cursor: pointer; }
button:focus-visible, textarea:focus-visible { outline: 3px solid #99b6ff; outline-offset: 2px; }
button:disabled { opacity: .5; cursor: not-allowed; }
.primary { color: #fff; background: #315fd6; border-color: #315fd6; }

after.content:
.cursor { display: inline-block; width: .5rem; height: 1rem; margin-left: .2rem; background: #315fd6; vertical-align: -2px; animation: blink .8s steps(2) infinite; }
@keyframes blink { 50% { opacity: 0; } }
.tool { max-width: 46rem; padding: .75rem 1rem; border-left: 3px solid #8298ca; background: #edf1f8; border-radius: 0 .7rem .7rem 0; }
.tool-trigger { width: 100%; height: auto; justify-content: space-between; padding: .1rem 0; }
.tool-heading { display: flex; align-items: center; gap: .55rem; font-size: .85rem; }
.tool-details { margin-top: .4rem; color: #526079; font-family: ui-monospace, monospace; font-size: .78rem; overflow-wrap: anywhere; }
.tool-details pre { margin: .25rem 0 .6rem; white-space: pre-wrap; }
.composer-wrap { padding: .6rem clamp(1rem, 8vw, 8rem) 1.3rem; background: linear-gradient(transparent, #f6f7f9 25%); }
.config { max-width: 52rem; margin: 0 auto .45rem; display: flex; gap: .45rem; flex-wrap: wrap; color: #5e6b80; font-size: .72rem; }
.config span { background: #e8ebf1; border-radius: 99px; padding: .25rem .55rem; }
